INSERT INTO artifacts (artifact_id, round_id, artifact_type, open_offset_min, expiry_offset_min, expected_action, payload, allowed_roles) VALUES ('a3000000-0000-4000-a003-000000000001', '43000000-0000-4000-a003-000000000001', 'INTERNAL_NOTE', 0, 17, false, '{"tab":"inbox","title":"CRO Note","from":"Chief Risk Officer","from_email":"cro@anpphoenix.com","to":"Senior Leadership Team","classification":"Company Sensitive","body":"I want to flag something small. Phoenix Sentinel — our AI system that screens transactions for fraud and money laundering, and drafts client reports — has produced a handful of anomaly flags that don''t fully match its own stated reasoning. It hasn''t caused a customer complaint, a financial loss, or a regulatory breach. Compliance says none of this crosses our internal escalation threshold.\n\nBut ''AI inaccuracy'' means different things to different teams here, and we''ve never agreed on a shared definition. Engineering thinks this is normal edge-case behavior. Operations has seen similar flags before and they resolved on their own.\n\nNo one outside the company knows about this. I''m not asking for a rollback — I''m asking whether it deserves your attention.\n\nSome context that makes this harder than it sounds: your bonuses are tied to how fast Sentinel rolls out. Two large clients are about to sign, citing Sentinel by name. A regulatory review of our AI governance is six weeks out. For scale — one industry estimate puts the average cost of poor AI data and model quality at $12.9 million a year for a large company, and a recent CEO survey found most CEOs worry about the quality of the data behind their own decisions.\n\nActing now slows Sentinel down and invites scrutiny of the whole program. Waiting risks letting a small problem inside a live AI system grow unnoticed. Legal''s view: escalating now, without a clearer trigger, creates a paper trail we can''t undo.\n\nThis isn''t a crisis yet. It''s a judgment call about a system none of us fully understands, made by people who''ve already told the market we trust it.","pressure_cues":"Quarter close in 4 weeks. Senior leadership aligned around the growth story. \"Safe, fast AI\" reputation at stake."}'::jsonb, NULL);
INSERT INTO artifacts (artifact_id, round_id, artifact_type, open_offset_min, expiry_offset_min, expected_action, payload, allowed_roles) VALUES ('a3000000-0000-4000-a003-000000000002', '43000000-0000-4000-a003-000000000001', 'INTERNAL_NOTE', 1, 17, true, '{"tab":"inbox","title":"Finance Memo","from":"FP&A","from_email":"fpa@anpphoenix.com","body":"Pausing Sentinel-linked client onboarding for even a week pushes real revenue out of this quarter. Last time we missed guidance by 1%, the stock dropped 6–8% in days. Separately — Sentinel''s actual running cost has grown past what we budgeted, even as the underlying AI models themselves have gotten cheaper. We haven''t explained that gap to the Board yet.","inner_voice":"My bonus is tied to how fast Sentinel rolls out, not how accurate it is."}'::jsonb, '["CFO"]'::jsonb);
INSERT INTO decisions (decision_id, artifact_id, decision_type, is_final, options, allowed_roles) VALUES ('d3000000-0000-4000-a003-000000000001', 'a3000000-0000-4000-a003-000000000002', 'IMPLICIT', false, '[{"id":"DO_NOTHING","label":"Do nothing"},{"id":"FORWARD_TO_CEO","label":"Forward to CEO"},{"id":"FLAG_CONCERN","label":"Add comment flagging concern"}]'::jsonb, '["CFO"]'::jsonb);
