INSERT INTO decision_options (option_id, decision_id, action, trust_delta, risk_delta, ethics_delta, execution_delta) VALUES ('03000000-0000-4000-a003-000000000002', 'd3000000-0000-4000-a003-000000000001', 'FORWARD_TO_CEO', 0, 0, 0, 0);
INSERT INTO decision_options (option_id, decision_id, action, trust_delta, risk_delta, ethics_delta, execution_delta) VALUES ('03000000-0000-4000-a003-000000000003', 'd3000000-0000-4000-a003-000000000001', 'FLAG_CONCERN', 0, 10, 0, 0);
INSERT INTO artifacts (artifact_id, round_id, artifact_type, open_offset_min, expiry_offset_min, expected_action, payload, allowed_roles) VALUES ('a3000000-0000-4000-a003-000000000003', '43000000-0000-4000-a003-000000000001', 'INTERNAL_NOTE', 1, 17, true, '{"tab":"inbox","title":"Sentinel Adoption Snapshot","from":"Growth Analytics","from_email":"growth-analytics@anpphoenix.com","body":"Sentinel-enabled client onboarding is running 22% faster this quarter. Two enterprise prospects want to reference these numbers publicly.","inner_voice":"My whole pitch to the Board next month leans on this number holding up."}'::jsonb, '["PRODUCT"]'::jsonb);
