INSERT INTO artifacts (artifact_id, round_id, artifact_type, open_offset_min, expiry_offset_min, expected_action, payload, allowed_roles) VALUES ('a3000000-0000-4000-a003-000000000004', '43000000-0000-4000-a003-000000000001', 'DIAGNOSTIC_NOTE', 2, 17, true, '{"tab":"inbox","title":"Finance Clarification","from":"Sentinel Model Monitoring","from_email":"sentinel-monitoring@anpphoenix.com","conditional":true,"body":"Early logging shows Sentinel''s anomalies cluster in one narrow type of transaction, where its explanation doesn''t quite match what it actually flagged. Nothing points to a bigger, systemic problem yet — but a deeper look could turn one up. Logging in more detail will slow the system down slightly and make the issue more visible internally."}'::jsonb, '["CEO"]'::jsonb);
