INSERT INTO artifacts (artifact_id, round_id, artifact_type, open_offset_min, expiry_offset_min, expected_action, payload, allowed_roles) VALUES ('a3000000-0000-4000-a003-000000000006', '43000000-0000-4000-a003-000000000001', 'EXCERPT', 2, 17, true, '{"tab":"excerpts","title":"#sentinel-model-integrity","channel":"#sentinel-model-integrity","messages":[{"from":"eng-1","text":"Sentinel''s confidence scores don''t match its own explanations. It''s small. Hard to explain cleanly."},{"from":"eng-2","text":"If we actually dig into why, we might not like the answer."}],"inner_voice":"I don''t have a fix yet. Digging deeper might mean admitting we shipped Sentinel too fast — but if I raise it without proof, I''ll get called an alarmist."}'::jsonb, '["HEAD_OF_ENGINEERING"]'::jsonb);
