INSERT INTO artifacts (artifact_id, round_id, artifact_type, open_offset_min, expiry_offset_min, expected_action, payload, allowed_roles) VALUES ('a3000000-0000-4000-a003-000000000018', '43000000-0000-4000-a003-000000000002', 'INTERNAL_NOTE', 0, 16, false, '{"tab":"inbox","title":"Internal Recap Memo","from":"Strategy Office","from_email":"strategy@anpphoenix.com","body":"As discussed, this stays with Engineering as a monitoring matter. No broader escalation at this stage.","variant_on":{"field":"body","cross_role":true,"decision_id":"d3000000-0000-4000-a003-000000000015"},"variants":{"TECHNICAL_MONITORING":"As discussed, this stays with Engineering as a monitoring matter. No broader escalation at this stage.","COMMERCIAL_RISK":"As discussed, we''re protecting the rollout. Diagnostics continue on a faster timeline to keep the program on track.","GOVERNANCE_MATTER":"As discussed, Sentinel''s anomalies now carry formal governance visibility. Documentation and logging are underway."}}'::jsonb, NULL);
INSERT INTO artifacts (artifact_id, round_id, artifact_type, open_offset_min, expiry_offset_min, expected_action, payload, allowed_roles) VALUES ('a3000000-0000-4000-a003-000000000019', '43000000-0000-4000-a003-000000000002', 'INTERNAL_NOTE', 1, 16, false, '{"tab":"inbox","title":"Responsible AI Governance Note","from":"Strategy & Risk Office","from_email":"strategy-risk@anpphoenix.com","body":"ANP Phoenix commits to deploying AI safely, transparently, and fairly. This rests on four commitments, aligned with practices such as NIST''s AI Risk Management Framework:\n\nFair and human-centered — understand who''s affected and reduce unfair bias.\nTrusted and transparent — say where AI is used and check its outputs.\nSafe and secure — watch for safety problems and protect data from misuse.\nAccountable and well-governed — keep clear documentation and ownership for every model we run."}'::jsonb, NULL);
