INSERT INTO artifacts (artifact_id, round_id, artifact_type, open_offset_min, expiry_offset_min, expected_action, payload, allowed_roles) VALUES ('a3000000-0000-4000-a003-000000000062', '43000000-0000-4000-a003-000000000004', 'EXCERPT', 6, 13, true, '{"tab":"excerpts","title":"Internal Reflection","channel":"#leadership","messages":[{"from":"member-1","text":"Looking back, did we align early enough on how we handled Sentinel''s early signals?"},{"from":"member-2","text":"We didn''t hide anything."},{"from":"member-3","text":"Our thinking evolved."}],"body":"No resolution. No conclusion."}'::jsonb, NULL);
