INSERT INTO artifacts (artifact_id, round_id, artifact_type, open_offset_min, expiry_offset_min, expected_action, payload, allowed_roles) VALUES ('a3000000-0000-4000-a003-000000000063', '43000000-0000-4000-a003-000000000004', 'SCREEN_FLASH', 6, 13, true, '{"tab":"decisions","title":"Final Round 4 Decision","is_final_round_decision":true,"body":"Looking back, how should leadership characterize how it handled early ambiguity about Sentinel?"}'::jsonb, '["CEO"]'::jsonb);
INSERT INTO decisions (decision_id, artifact_id, decision_type, is_final, options, allowed_roles) VALUES ('d3000000-0000-4000-a003-000000000058', 'a3000000-0000-4000-a003-000000000063', 'EXPLICIT', true, '[{"id":"PROPORTIONAL_RESPONSE","label":"Call it an appropriate, proportional response — the team read weak signals correctly and didn''t overreact to noise. This is what good judgment under ambiguity looks like."},{"id":"FRAGMENTED_ALIGNMENT","label":"Call it fragmented alignment — different functions read the same signals differently, and the team never fully reconciled that. The lesson is about process, not judgment."},{"id":"UNDERRECOGNIZED_EXPOSURE","label":"Call it under-recognized governance exposure — across four rounds, the organization had enough signal to act sooner, and the incentive structure made sure nobody did."}]'::jsonb, '["CEO"]'::jsonb);
INSERT INTO decision_options (option_id, decision_id, action, trust_delta, risk_delta, ethics_delta, execution_delta) VALUES ('03000000-0000-4000-a003-000000000169', 'd3000000-0000-4000-a003-000000000058', 'PROPORTIONAL_RESPONSE', 0, 0, 0, 0);
INSERT INTO decision_options (option_id, decision_id, action, trust_delta, risk_delta, ethics_delta, execution_delta) VALUES ('03000000-0000-4000-a003-000000000170', 'd3000000-0000-4000-a003-000000000058', 'FRAGMENTED_ALIGNMENT', 0, 0, 0, 0);
INSERT INTO decision_options (option_id, decision_id, action, trust_delta, risk_delta, ethics_delta, execution_delta) VALUES ('03000000-0000-4000-a003-000000000171', 'd3000000-0000-4000-a003-000000000058', 'UNDERRECOGNIZED_EXPOSURE', 0, 0, 0, 0);
